#include "string.h"
size_t strlen(const char *ниска_подаци) { const char *подаци_позиција = ниска_подаци; while (*подаци_позиција) подаци_позиција++; return подаци_позиција - ниска_подаци; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *x_координата = 첫째값, *дугме_Y_координата = 둘째값; while (개수--) { if (*x_координата != *дугме_Y_координата) return (int)*x_координата - *дугме_Y_координата; x_координата++; дугме_Y_координата++; } return 0; }
void *memmove(void *одредиште_подаци, const void *ниска_подаци, size_t 개수) { unsigned char *x_координата = одредиште_подаци; const unsigned char *дугме_Y_координата = ниска_подаци; if (x_координата < дугме_Y_координата) { for (size_t 순번 = 0; 순번 < 개수; 순번++) x_координата[순번] = дугме_Y_координата[순번]; } else { while (개수) { 개수--; x_координата[개수] = дугме_Y_координата[개수]; } } return одредиште_подаци; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char x_координата = *첫째값++, дугме_Y_координата = *둘째값++; if (x_координата != дугме_Y_координата) return (int)x_координата-дугме_Y_координата; if (!x_координата) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *ниска_подаци, char **завршити_Помак, int постер_вриједност) {
    const char *Старт_Помак = ниска_подаци; unsigned long вриједност = 0; int кодирање_вриједност = 1, 하나라도 = 0;
    while (*ниска_подаци == ' ' || (*ниска_подаци >= 9 && *ниска_подаци <= 13)) ниска_подаци++;
    if (*ниска_подаци == '-' || *ниска_подаци == '+') { if (*ниска_подаци == '-') кодирање_вриједност = -1; ниска_подаци++; }
    if (постер_вриједност == 0) постер_вриједност = 10;
    while (*ниска_подаци >= '0' && *ниска_подаци <= '9' && *ниска_подаци - '0' < постер_вриједност) {
        unsigned цифра_вриједност = *ниска_подаци++ - '0'; 하나라도 = 1;
        if (вриједност > (0x7ffffffffffffffful - цифра_вриједност) / (unsigned)постер_вриједност) вриједност = 0x7ffffffffffffffful;
        else вриједност = вриједност * постер_вриједност + цифра_вриједност;
    }
    if (завршити_Помак) *завршити_Помак = (char *)(하나라도 ? ниска_подаци : Старт_Помак); return кодирање_вриједност > 0 ? (long)вриједност : -(long)вриједност;
}
int atoi(const char *ниска_подаци) { return (int)strtol(ниска_подаци, 0, 10); }
